type WardSection = "ward-overview" | "ward-risk" | "population-exposure" | "ward-trends";
type View = "overview" | "heat-map" | "heat-trend" | "wards" | "health-impact" | WardSection | "forecast" | "ai-copilot" | "alerts" | "reports" | "response" | "settings";
type OverviewInsight = { ward: HistoricalWardRisk; metrics: ReturnType<typeof thermalMetrics>; prediction: PrototypeHealthPrediction };
type SearchItem = { title: string; detail: string; group: "Wards" | "Alerts" | "Reports" | "Sections & concepts"; view: View; wardId?: number; keywords?: string };
const riskClass = (risk: RiskLevel) => `risk-${risk.toLowerCase().replaceAll(" ", "-")}`;
const activeRisk = (risk: RiskLevel) => `${riskClass(risk)} text-[var(--risk)]`;
function getHTSIBand(htsi: number): RiskLevel { return htsiRiskLevel(htsi); }
function getRelevantHealthEffects(htsi: number): [string, string][] {
  const band = getHTSIBand(htsi);
  const effects: Record<RiskLevel, [string, string][]> = {
    Low: [["Dehydration", "Mild dehydration risk may increase with prolonged outdoor exposure."]],
    Moderate: [["Dehydration", "Increased dehydration risk with prolonged outdoor exposure."], ["Heat exhaustion", "Risk may increase during peak afternoon heat."]],
    High: [["Dehydration", "High dehydration risk during prolonged exposure."], ["Heat exhaustion", "Increased risk during peak heat."], ["Heatstroke", "Risk becomes significant with prolonged exposure."], ["Cardiovascular / respiratory stress", "Greater physiological stress expected."]],
    "Very High": [["Dehydration", "Very high likelihood during prolonged exposure."], ["Heat exhaustion", "Substantial risk during peak heat."], ["Heatstroke", "Elevated risk, especially for vulnerable populations."], ["Cardiovascular / respiratory stress", "Substantial thermal stress expected."]],
    Extreme: [["Dehydration", "Very high heat-related dehydration risk."], ["Heat exhaustion", "Very high risk during exposure."], ["Heatstroke", "Serious risk during prolonged exposure."], ["Cardiovascular / respiratory stress", "Severe thermal stress expected."]],
  };
  return effects[band];
}

