    wards: "M4 21V5l8-3 8 3v16M9 21v-4h6v4M8 8h.01M12 8h.01M16 8h.01M8 12h.01M12 12h.01M16 12h.01",
    chart: "M3 3v18h18M7 16l4-5 3 2 5-7", bell: "M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9", report: "M6 3h9l3 3v15H6zM9 12h6m-6 4h6",
    settings: "M10.3 4.15 10 2.8h4l-.3 1.35c.58.18 1.12.4 1.62.7l1.18-.74 2.83 2.83-.74 1.18c.3.5.52 1.04.7 1.62l1.35.3v4l-1.35.3c-.18.58-.4 1.12-.7 1.62l.74 1.18-2.83 2.83-1.18-.74c-.5.3-1.04.52-1.62.7L14 21.2h-4l.3-1.35a7.94 7.94 0 0 1-1.62-.7l-1.18.74-2.83-2.83.74-1.18a7.94 7.94 0 0 1-.7-1.62L3.35 14v-4l1.35-.3c.18-.58.4-1.12.7-1.62l-.74-1.18L7.5 4.07l1.18.74c.5-.3 1.04-.52 1.62-.7ZM12 15.25A3.25 3.25 0 1 0 12 8.75a3.25 3.25 0 0 0 0 6.5Z", trend: "M3 17l6-6 4 4 7-8M14 7h7v7", chevron: "m9 18 6-6-6-6", menu: "M4 7h16M4 12h16M4 17h16", moon: "M20.4 14.2A8.5 8.5 0 0 1 9.8 3.6 8.5 8.5 0 1 0 20.4 14.2Z", sun: "M12 3v2m0 14v2m9-9h-2M5 12H3m15.36-6.36-1.42 1.42M7.06 16.94l-1.42 1.42m12.72 0-1.42-1.42M7.06 7.06 5.64 5.64M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z", phone: "M7.5 3.5 5.1 5.2c-.75.54-.98 1.54-.54 2.35 2.5 4.61 6.29 8.4 10.9 10.9.81.44 1.81.21 2.35-.54l1.69-2.4a1.75 1.75 0 0 0-.35-2.36l-2.25-1.76a1.75 1.75 0 0 0-2.34.1l-1.34 1.3a12.9 12.9 0 0 1-2.01-2.01l1.3-1.34a1.75 1.75 0 0 0 .1-2.34L9.86 3.85a1.75 1.75 0 0 0-2.36-.35Z",
